using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Tag", menuName = "Data/Battle/Battle Actions/Tags/Tag", order = 0)]
public class Tag : ScriptableObject
{
	[SerializeField]
	protected string tagID;

	[SerializeField]
	private bool enableCustomActionIDNameForDescription;

	[SerializeField]
	[ShowIf("enableCustomActionIDNameForDescription")]
	private string customActionIDNameForDescription;

	[SerializeField]
	[ShowAssetPreview(64, 64)]
	private Sprite tagSprite;

	[SerializeField]
	private string[] tagDifferentConjugationID;

	[SerializeField]
	private bool dontTintDescription;

	public Sprite TagSprite => tagSprite;

	public string[] TagDifferentConjugationID => tagDifferentConjugationID;

	protected string tagIDName => tagID + "_N";

	public string TagIDDescription => tagID + "_T";

	public bool DontTintDescription => dontTintDescription;

	public virtual string GetTagName()
	{
		string text = "";
		text = ((!enableCustomActionIDNameForDescription) ? tagIDName : customActionIDNameForDescription);
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(text);
	}

	public virtual string GetTagDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(TagIDDescription);
	}

	public string GetTagDifferentConjugation(int index)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(tagDifferentConjugationID[index]);
	}
}
